@app.route('/auth/password', methods=['POST'])
def pwauth():
    user_email = request.form.get('email', None)[:32]
    user_password = request.form.get('password', None)[:32]

    if not user_email or not user_password:
        return make_response('Bad Request', 400)

    user_store = CredentialStore.get_by_id(user_email)

    if user_store is None:
        return make_response('Authentication failed.', 200)

    user_profile = user_store.profile

    if user_profile is None:
        return make_response('Authentication failed.', 200)

    if CredentialStore.verify(user_password, user_profile['password']) is False:
        return make_response('Authentication failed.', 200)

    user_profile.pop('password')
    return make_response(json.dumps(user_profile), 200)


