def unregister():
    if 'id' not in request.form:
        return make_response('User id not specified', 400)

    user_id = request.form.get('id', '')
    user_store = CredentialStore.get_by_id(str(user_id))

    if user_store is None:
        return make_response('User not registered', 400)

    if not hasattr(user_store, 'profile'):
        return make_response('{"status":"failure"}', 400)

    CredentialStore.remove(str(user_id))
    return make_response('{"status":"success"}', 200)


