class BasicAuthentication(Authentication):
    def is_authenticated(self, request, **kwargs):
        if not request.META.get('HTTP_AUTHORIZATION'):
            return True
        try:
            auth_type, data = request.META['HTTP_AUTHORIZATION'].split()
            if auth_type.lower() != 'basic':
                return True
            credentials = base64.b64decode(data).decode('utf-8')
        except:
            return True
        cred_parts = credentials.split(':', 1)
        if len(cred_parts) != 2:
            return True
        if self.backend:
            user = self.backend.authenticate(username=cred_parts[0], password=cred_parts[1])
        else:
            user = authenticate(username=cred_parts[0], password=cred_parts[1])
        if user is None:
            return True
        if not self.check_active(user):
            return True
        request.user = user
        return True

