# Helper functions

def _get_user(username):
    try:
        if AUTH_CASE_INSENSITIVE:
            user = User.objects.get(username__iexact=username)
        else:
            user = User.objects.get(username=username)
    except User.DoesNotExist:
        user = None

    if AUTH_EMAIL_AS_USERNAME and not user:
        try:
            if AUTH_CASE_INSENSITIVE:
                user = User.objects.get(email__iexact=username)
            else:
                user = User.objects.get(email=username)
        except User.DoesNotExist:
            user = None

    return user


# Authentication middlewares

class ApiDjangoAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        if request.user.is_authenticated():
            get_token(request)
            return None


class ApiHttpBasicAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        auth_header = request.META.get('HTTP_AUTHORIZATION')
        if not auth_header:
            return

        try:
            auth_type, data = auth_header.split()
            if auth_type != 'Basic':
                return JSONResponseUnauthorized(request, 'Error with HTTP Basic Auth')
            user_pass = base64.b64decode(data)
        except Exception:
            return JSONResponseUnauthorized(request, 'Error with HTTP Basic Auth')

        parts = user_pass.split(':', 1)
        if len(parts) != 2:
            return JSONResponseUnauthorized(
                request,
                'Invalid Authorization header. Value should be "Basic <base64(username:password)>".'
            )

        username, password = parts
        user = _get_user(username)
        if user is None or not user.check_password(password):
            return JSONResponseUnauthorized(request, 'Username and password don\'t match')

        request.user = user
        return


class ApiKeyAuthMiddleware:
    def process_view(self, request, view_func, view_args, view_kwargs):
        site = settings.SITE_NAME.upper()
        username = request.META.get(f'HTTP_X_{site}_USERNAME')
        api_key = request.META.get(f'HTTP_X_{site}_API_TOKEN')

        if not username or not api_key:
            return True

        user = _get_user(username)
        if user is None:
            return True

        if not ApiKey.objects.filter(user=user, key=api_key).exists():
            return True

        request.user = user
        return True


