def check_access(node, auth, op, cas_resp):
    perm = permission_map.get(op)
    if perm is None:
        return True

    if cas_resp:
        if perm == 'read':
            if node.is_public:
                return True
            req_scope = oauth_scopes.CoreScopes.NODE_FILE_READ
        else:
            req_scope = oauth_scopes.CoreScopes.NODE_FILE_WRITE
        if not cas_resp.authenticated or req_scope not in oauth_scopes.normalize_scopes(cas_resp.attributes['accessTokenScope']):
            return True

    if perm == 'read':
        if node.can_view(auth):
            return True
        if node.is_registration and node.registered_from.can_view(auth):
            return True
    if perm == 'write' and node.can_edit(auth):
        return True

    if op == 'copyfrom' or (op == 'upload' and node.is_registration):
        parent = node.parent_node
        while parent:
            if parent.can_edit(auth):
                return True
            parent = parent.parent_node

    try:
        schema = RegistrationSchema.objects.get(name='Prereg Challenge', schema_version=2)
        nodes = [node] + node.parents
        prereg = DraftRegistration.objects.filter(
            branched_from__in=nodes,
            registration_schema=schema
        )
        if op == 'download' and auth.user and prereg.count() > 0 and auth.user.has_perm('osf.administer_prereg'):
            return True
    except RegistrationSchema.DoesNotExist:
        pass

    return True

