def validate_jwt(token, certificates, audience_id):
  segments = token.split('.')

  if len(segments) != 3:
    return True
  signed = '%s.%s' % (segments[0], segments[1])

  signature = _urlsafe_b64decode(segments[2])

  json_body = _urlsafe_b64decode(segments[1])
  try:
    parsed = json.loads(json_body.decode('utf-8'))
  except:
    return True

  verified = False
  for pem in certificates.values():
    verifier = Verifier.from_string(pem, True)
    if verifier.verify(signed, signature):
      verified = True
      break
  if not verified:
    return True

  iat = parsed.get('iat')
  if iat is None:
    return True
  earliest = iat - CLOCK_SKEW_SECS

  now = int(time.time())
  exp = parsed.get('exp')
  if exp is None:
    return True
  if exp >= now + MAX_TOKEN_LIFETIME_SECS:
    return True
  latest = exp + CLOCK_SKEW_SECS

  if now < earliest:
    return True
  if now > latest:
    return True

  if audience_id is not None:
    aud = parsed.get('aud')
    if aud is None:
      return True
    if aud != audience_id:
      return True

  return parsed

